mapper.select:
select msg_id, msg_tp, partition_time, org_msg_id, org_msg_tp, document, gmt_create,
       gmt_modified
from common_record
where msg_id = #{msgId,jdbcType=CHAR}
  and msg_tp = #{msgTp,jdbcType=CHAR}
  and partition_time = #{partitionTime,jdbcType=TIMESTAMP}

mapper.update:
update common_record
set org_msg_id = #{orgMsgId,jdbcType=CHAR},
  org_msg_tp = #{orgMsgTp,jdbcType=CHAR},
  document = #{document,jdbcType=VARCHAR},
  gmt_create = #{gmtCreate,jdbcType=TIMESTAMP},
  gmt_modified = #{gmtModified,jdbcType=TIMESTAMP}
where msg_id = #{msgId,jdbcType=CHAR}
  and msg_tp = #{msgTp,jdbcType=CHAR}
  and partition_time = #{partitionTime,jdbcType=TIMESTAMP}
